// 추출 함수
// ───────────────────────────────────────────────────────────

/**
 * 텍스트(상품명, 키워드 등)에서 매칭된 1차 농산물 라벨 추출.
 *
 * @example
 *   extractProductLabels("샤인머스캣 2kg") → ["포도"]
 *   extractProductLabels("참외 + 토마토 세트") → ["참외", "토마토"]
 *   extractProductLabels("딸기잼") → ["딸기"] (환원 적용 시)
 */
export function extractProductLabels(text: string): string[] {
  if (!text) return [];
  const found = new Set<string>();
  for (const [label, pattern] of Object.entries(PRODUCT_KEYWORDS)) {
    if (pattern.test(text)) {
      found.add(label);
    }
  }
  return [...found];
}

/**
 * 텍스트에서 가공품 → 원료 환원으로 1차 농산물 추가 추출.
 *
 * @example
 *   reduceToPrimary("딸기잼 세트") → ["딸기"]
 *   reduceToPrimary("감귤청과 도라지배즙") → ["감귤", "배", "약초"]
 */
export function reduceToPrimary(text: string): string[] {
  if (!text) return [];
  const found = new Set<string>();
  for (const [keyword, primaryList] of Object.entries(PROCESSED_TO_PRIMARY)) {
    if (text.includes(keyword)) {
      for (const p of primaryList) found.add(p);
    }
  }
  return [...found];
}

/**
 * 1차 추출 + 가공품 환원 합쳐서 모든 후보 키워드 반환.
 * 자동 매칭 진입점.
 */
export function extractAllKeywords(text: string): {
  primary: string[]; //                직접 매칭된 1차 농산물
  reduced: string[]; //                가공품 → 환원된 1차 농산물
  combined: string[]; //               합친 unique 키워드
} {
  const primary = extractProductLabels(text);
  const reduced = reduceToPrimary(text);
  const combined = [...new Set([...primary, ...reduced])];
  return { primary, reduced, combined };
}
